UPDATE `order` SET
shipping_address = #{shippingAddress}, status = #{status}, pay_time = #{payTime}, ship_time = #{shipTime}, receive_time = #{receiveTime},
WHERE id = #{id}

mapper.select:
SELECT COALESCE(SUM(o.total_amount), 0) 
FROM `order` o 
JOIN order_item oi ON o.id = oi.order_id 
WHERE oi.merchant_id = #{merchantId} 
  AND o.status <> 4

  AND o.create_time >= #{start} 


  AND o.create_time <= #{end}

SELECT o.id, o.order_no as orderNo, o.user_id as userId, o.total_amount as totalAmount, o.status, o.shipping_address as shippingAddress, o.receiver_name as receiverName, o.receiver_phone as receiverPhone, o.remark, o.group_order_no as groupOrderNo, o.create_time as createTime, o.pay_time as payTime, o.ship_time as shipTime, o.receive_time as receiveTime, u.username as userName FROM `order` o JOIN order_item oi ON o.id = oi.order_id LEFT JOIN user u ON o.user_id = u.id WHERE oi.merchant_id = #{merchantId}
AND o.status = #{status}
ORDER BY o.create_time DESC

SELECT oi.product_id as productId, oi.product_name as productName, COALESCE(SUM(oi.quantity), 0) as salesCount, COALESCE(SUM(oi.subtotal), 0) as salesAmount, COALESCE(SUM(oi.subtotal) / NULLIF(SUM(oi.quantity), 0), 0) as avgPrice FROM order_item oi WHERE oi.merchant_id = #{merchantId}
AND oi.create_time >= #{startTime}
AND oi.create_time <= #{endTime}
GROUP BY oi.product_id, oi.product_name ORDER BY salesCount DESC salesAmount DESC salesCount DESC
LIMIT 20

SELECT DISTINCT o.id, o.order_no as orderNo, o.user_id as userId, o.total_amount as totalAmount, o.status, o.shipping_address as shippingAddress, o.receiver_name as receiverName, o.receiver_phone as receiverPhone, o.remark, o.group_order_no as groupOrderNo, o.create_time as createTime, o.pay_time as payTime, o.ship_time as shipTime, o.receive_time as receiveTime, u.username as userName FROM `order` o JOIN order_item oi ON o.id = oi.order_id LEFT JOIN user u ON o.user_id = u.id WHERE oi.merchant_id = #{merchantId}
AND o.status IN
#{s}
AND ( o.order_no LIKE CONCAT('%', #{keyword}, '%') OR o.receiver_name LIKE CONCAT('%', #{keyword}, '%') OR o.receiver_phone LIKE CONCAT('%', #{keyword}, '%') )
AND o.create_time >= #{startDate}
AND o.create_time <= #{endDate}
ORDER BY o.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(DISTINCT o.id)
FROM `order` o
JOIN order_item oi ON o.id = oi.order_id
WHERE oi.merchant_id = #{merchantId}

    AND o.status IN

        #{s}



    AND (
        o.order_no LIKE CONCAT('%', #{keyword}, '%')
        OR o.receiver_name LIKE CONCAT('%', #{keyword}, '%')
        OR o.receiver_phone LIKE CONCAT('%', #{keyword}, '%')
    )


    AND o.create_time >= #{startDate}


    AND o.create_time <= #{endDate}

mapper.update:
UPDATE `order` o
JOIN order_item oi ON o.id = oi.order_id
SET o.status = -1
WHERE o.id = #{id}
  AND oi.merchant_id = #{merchantId}
  AND o.status IN (0, 1)

UPDATE `order` SET
    status = 2,
    express_company = #{expressCompany},
    tracking_no = #{trackingNo},
    ship_time = #{shipTime}
WHERE id = #{id}

mapper.select:
SELECT o.id, o.order_no as orderNo, o.total_amount as totalAmount, o.status, o.create_time as createTime, oi.product_id as productId, oi.product_name as productName, oi.product_price as productPrice, oi.quantity as quantity FROM `order` o JOIN order_item oi ON o.id = oi.order_id WHERE oi.merchant_id = #{merchantId} AND o.status IN (2, 3)
AND o.create_time >= #{startDate}
AND o.create_time <= #{endDate}
ORDER BY o.create_time DESC
